46	/// パスの正規化のうち、バージョン要素の置き換えを除いた部分。フラグ判定にはこちらを使う
47	/// （`C:\Users\1.2.3\...` のような置き換えで場所の判定が変わらないように）
48	fn normalize_basic(os: Os, path: &str) -> (String, bool) {
49	    match os {
50	        Os::Windows => {
51	            let path = path.strip_prefix(r"\\?\").unwrap_or(path);
52	            (path.replace('/', "\\").to_ascii_lowercase(), false)
53	        }
54	        Os::Linux => match path.strip_suffix(" (deleted)") {
55	            Some(rest) => (rest.to_string(), true),
56	            None => (path.to_string(), false),
57	        },
58	    }
59	}
