61	/// パスを識別キーに正規化する（§2.2 の 1〜3）
62	pub fn normalize_path(os: Os, path: &str) -> Identity {
63	    let (path, deleted) = normalize_basic(os, path);
64	    let sep = os.separator();
65	    let key = path
66	        .split(sep)
67	        .map(|element| {
68	            if is_version_element(element) {
69	                "*"
70	            } else {
71	                element
72	            }
73	        })
74	        .collect::<Vec<_>>()
75	        .join(&sep.to_string());
76	    Identity { key, deleted }
77	}
