79	/// `(v|app-)?数字(.数字)+` の後に、任意で `[-+_.]` と英数字・`.` の列が続く形か。
80	/// 更新のたびに変わるディレクトリ名やファイル名を 1 つの識別キーにまとめるために使う。
81	/// `python3` や `x64` のように `.` を含まない数字は、バージョンとみなさない
82	fn is_version_element(element: &str) -> bool {
83	    let lower = element.to_ascii_lowercase();
84	    let rest = lower
85	        .strip_prefix("app-")
86	        .or_else(|| lower.strip_prefix('v'))
87	        .unwrap_or(&lower);
88	    let bytes = rest.as_bytes();
89	
90	    let digits = |from: usize| {
91	        bytes[from..]
92	            .iter()
93	            .take_while(|b| b.is_ascii_digit())
94	            .count()
95	    };
96	    let first = digits(0);
97	    if first == 0 {
98	        return false;
99	    }
100	    let mut pos = first;
101	    let mut groups = 0;
102	    // `.` の後に数字が続く限りだけ食う。`1.2.3.exe` の `.exe` は後ろの列として扱う
103	    while pos < bytes.len() && bytes[pos] == b'.' {
104	        let n = digits(pos + 1);
105	        if n == 0 {
106	            break;
107	        }
108	        pos += 1 + n;
109	        groups += 1;
110	    }
111	    if groups == 0 {
112	        return false;
113	    }
114	    match bytes.get(pos) {
115	        None => true,
116	        Some(b'-' | b'+' | b'_' | b'.') => bytes[pos + 1..]
117	            .iter()
118	            .all(|b| b.is_ascii_alphanumeric() || *b == b'.'),
119	        Some(_) => false,
120	    }
121	}
