225	/// masquerade: Windows のシステムプロセスの名前なのに、置き場所が違う。
226	/// パスが取れないもの（`path` が None）は判定しない。Linux では常に false
227	pub fn is_masquerade(roots: &Roots, name: &str, path: Option<&str>) -> bool {
228	    if roots.os != Os::Windows {
229	        return false;
230	    }
231	    let Some(path) = path else {
232	        return false;
233	    };
234	    let name = name.to_ascii_lowercase();
235	    let (path, _) = normalize_basic(roots.os, path);
236	    // 名前の表に無ければ対象外。explorer.exe だけは %SystemRoot% 直下が正しい置き場所
237	    let allowed: Vec<String> = if name == "explorer.exe" {
238	        vec![roots.system_root.clone()]
239	    } else if SYSTEM_PROCESS_NAMES.contains(&name.as_str()) {
240	        vec![
241	            format!(r"{}\system32", roots.system_root),
242	            format!(r"{}\syswow64", roots.system_root),
243	        ]
244	    } else {
245	        return false;
246	    };
247	    // 親ディレクトリの完全一致で見る。`system32\evil\svchost.exe` も不正にする
248	    let parent = path.rsplit_once('\\').map_or("", |(dir, _)| dir);
249	    !allowed.iter().any(|dir| dir == parent)
250	}
