252	/// 根のプロセスとその子孫を除いたプロセス一覧を返す。
253	///
254	/// `roots` は (PID, 起動時刻)。kuda 自身と実行中の調査プロセスを渡す。
255	/// 判断はすべて「除外しすぎない」側に倒す。除外は見えなくする操作なので、
256	/// 誤って除くより、kuda 自身が未知として見えるほうがまだ安全だから。
257	/// - 根は、一覧に同じ PID がいて起動時刻が一致するときだけ生きているとみなす（PID 再利用対策）
258	/// - 親子は、親の起動時刻 ≤ 子の起動時刻のときだけたどる。
259	///   どちらかの起動時刻が None のときは確かめられないので、たどらない
260	pub fn without_descendants<'a>(
261	    processes: &'a [ProcessInfo],
262	    roots: &[(u32, i64)],
263	) -> Vec<&'a ProcessInfo> {
264	    let by_pid: HashMap<u32, &ProcessInfo> = processes.iter().rev().map(|p| (p.pid, p)).collect();
265	    let mut children: HashMap<u32, Vec<&ProcessInfo>> = HashMap::new();
266	    for p in processes {
267	        if let Some(ppid) = p.ppid {
268	            children.entry(ppid).or_default().push(p);
269	        }
270	    }
271	
272	    let mut excluded: HashSet<u32> = HashSet::new();
273	    let mut queue: Vec<&ProcessInfo> = roots
274	        .iter()
275	        .filter_map(|&(pid, started)| {
276	            by_pid
277	                .get(&pid)
278	                .copied()
279	                .filter(|p| p.started == Some(started))
280	        })
281	        .collect();
282	    while let Some(parent) = queue.pop() {
283	        if !excluded.insert(parent.pid) {
284	            continue;
285	        }
286	        for &child in children.get(&parent.pid).into_iter().flatten() {
287	            match (parent.started, child.started) {
288	                (Some(ps), Some(cs)) if ps <= cs => queue.push(child),
289	                _ => {}
290	            }
291	        }
292	    }
293	    processes
294	        .iter()
295	        .filter(|p| !excluded.contains(&p.pid))
296	        .collect()
297	}
