299	/// `*`（区切りも跨ぐ）だけを扱う glob。大文字小文字は区別しない
300	/// （パターンもパスも小文字にそろえる。Linux のパスも同じ扱いにして規則を 1 つにする）
301	pub fn glob_match(pattern: &str, text: &str) -> bool {
302	    let pattern: Vec<char> = pattern.to_lowercase().chars().collect();
303	    let text: Vec<char> = text.to_lowercase().chars().collect();
304	    let (mut p, mut t) = (0, 0);
305	    // 直近の `*` の位置と、そのとき `*` に食わせていた text の終端
306	    let mut star: Option<(usize, usize)> = None;
307	    while t < text.len() {
308	        if p < pattern.len() && pattern[p] == '*' {
309	            star = Some((p, t));
310	            p += 1;
311	        } else if p < pattern.len() && pattern[p] == text[t] {
312	            p += 1;
313	            t += 1;
314	        } else if let Some((sp, st)) = star {
315	            p = sp + 1;
316	            t = st + 1;
317	            star = Some((sp, st + 1));
318	        } else {
319	            return false;
320	        }
321	    }
322	    pattern[p..].iter().all(|&c| c == '*')
323	}
